import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { positionLocal, mix, vec3, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, Color } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#101015',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#121218' }, { at: 1, hex: '#0b0b10' }],
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findText = (role, idx = 0) => {
    let count = 0;
    for (const it of items) {
      if (it.role === role) {
        if (count === idx) return it.text;
        count++;
      }
    }
    return null;
  };

  const BAND_W = 6.8;
  const BAND_H = 2.0;

  const group = new Group();

  // ---- Backdrop stage plane (behind band) ----
  const stopTop = new Color(colors.gradientStops?.[0]?.hex ?? '#121218');
  const stopBot = new Color(colors.gradientStops?.[1]?.hex ?? '#0b0b10');

  const stageGeo = new PlaneGeometry(7, 6);
  const stageMat = new MeshStandardNodeMaterial();
  {
    const t = positionLocal.y.mul(1 / 6).add(0.5);
    stageMat.colorNode = mix(
      vec3(stopBot.r, stopBot.g, stopBot.b),
      vec3(stopTop.r, stopTop.g, stopTop.b),
      t.clamp(0, 1)
    );
    stageMat.roughness = 0.9;
    stageMat.metalness = 0.0;
  }
  const stage = new Mesh(stageGeo, stageMat);
  stage.position.set(0, 0, -2.5);
  group.add(stage);

  // ---- Footer band ----
  const band = new Group();
  band.position.set(0, 0, 0);

  const bandGeo = new PlaneGeometry(BAND_W, BAND_H);
  const bandMat = new MeshStandardNodeMaterial();
  {
    const t = positionLocal.y.mul(1 / BAND_H).add(0.5);
    bandMat.colorNode = mix(
      vec3(stopBot.r, stopBot.g, stopBot.b),
      vec3(stopTop.r, stopTop.g, stopTop.b),
      t.clamp(0, 1)
    );
    bandMat.roughness = 0.6;
    bandMat.metalness = 0.2;
  }
  const bandMesh = new Mesh(bandGeo, bandMat);
  band.add(bandMesh);

  // ---- Hairline rules ----
  const hairColor = new Color('#23232b');
  const makeHairline = (yPos) => {
    const g = new PlaneGeometry(BAND_W, 0.006);
    const m = new MeshStandardNodeMaterial();
    m.colorNode = vec3(hairColor.r, hairColor.g, hairColor.b);
    m.roughness = 0.35;
    m.metalness = 0.4;
    const mesh = new Mesh(g, m);
    mesh.position.set(0, yPos, 0.01);
    return mesh;
  };
  // top edge hairline
  band.add(makeHairline(BAND_H / 2 - 0.003));
  // legal separator hairline (0.375 + 0.25 above bottom)
  const legalY = -BAND_H / 2 + 0.375;
  band.add(makeHairline(legalY + 0.25 + 0.125));

  // ---- Accent bar ----
  const accentColor = new Color(colors.accent ?? '#ff2a38');
  {
    const g = new PlaneGeometry(0.3, 0.02);
    const m = new MeshStandardNodeMaterial();
    m.colorNode = vec3(accentColor.r, accentColor.g, accentColor.b);
    m.emissiveNode = vec3(accentColor.r, accentColor.g, accentColor.b).mul(1.4);
    m.roughness = 0.5;
    m.metalness = 0.1;
    const bar = new Mesh(g, m);
    bar.position.set(-BAND_W / 2 + 0.75, 0.2, 0.015);
    band.add(bar);
  }

  const paper = colors.paper ?? '#e8ecf2';

  const addText = (str, x, y, opts) => {
    if (!str) return null;
    const mesh = ctx.fontAtlas.createText(str, opts);
    mesh.position.set(x, y, 0.02);
    band.add(mesh);
    return mesh;
  };

  // ---- Wordmark (left block) ----
  const leftX = -BAND_W / 2 + 0.5;
  addText(findText('wordmark') ?? 'NOVA ATELIER', leftX, 0.5, {
    fontSize: 34,
    color: paper,
    align: 'left',
    letterSpacingPx: 1,
  });

  // ---- Link columns ----
  const columnHeaders = [];
  const columnLinks = [];
  {
    // gather columns from ordered items
    let curHeader = null;
    let curLinks = [];
    for (const it of items) {
      if (it.role === 'column-header') {
        if (curHeader) { columnHeaders.push(curHeader); columnLinks.push(curLinks); }
        curHeader = it.text;
        curLinks = [];
      } else if (it.role === 'link') {
        curLinks.push(it.text);
      }
    }
    if (curHeader) { columnHeaders.push(curHeader); columnLinks.push(curLinks); }
  }

  const colStartX = -BAND_W / 2 + 2.4;
  const colWidth = 1.2;
  const gutter = 0.375;
  const linkMeshes = [];

  for (let c = 0; c < columnHeaders.length; c++) {
    const cx = colStartX + c * (colWidth + gutter);
    const headerY = BAND_H / 2 - 0.45;
    addText(columnHeaders[c], cx, headerY, {
      fontSize: 9,
      color: paper,
      align: 'left',
      letterSpacingPx: 2,
    });
    const links = columnLinks[c] ?? [];
    for (let i = 0; i < links.length; i++) {
      const ly = headerY - 0.32 - i * 0.3;
      const m = addText(links[i], cx, ly, {
        fontSize: 13,
        color: paper,
        align: 'left',
      });
      if (m) linkMeshes.push(m);
    }
  }

  // ---- Legal line ----
  addText(findText('legal') ?? '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
    leftX, legalY, {
      fontSize: 9,
      color: '#8a8a94',
      align: 'left',
      letterSpacingPx: 0.5,
    });

  group.add(band);

  // ---- Node-local rim/key light (upper-left graze) ----
  const key = new DirectionalLight(0xffffff, 1.1);
  key.position.set(-3, 3, 4);
  group.add(key);
  const rim = new DirectionalLight(new Color(accentColor).getHex(), 0.6);
  rim.position.set(3, -1, 3);
  group.add(rim);

  // ---- Mount animation: single fade-up of the whole band ----
  band.position.y = 0.2;
  let bandOpacity = { v: 0 };
  bandMesh.material.opacity = 0;
  bandMesh.material.transparent = true;

  const tl = gsap.timeline();
  tl.to(band.position, {
    y: 0,
    duration: 0.5,
    ease: 'power2.out',
  }, 0);
  tl.to(bandOpacity, {
    v: 1,
    duration: 0.5,
    ease: 'power2.out',
    onUpdate: () => {
      band.traverse((o) => {
        if (o.material) {
          o.material.transparent = true;
          o.material.opacity = bandOpacity.v;
        }
      });
    },
  }, 0);

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    tl.kill();
    group.traverse((o) => {
      if (o.geometry) o.geometry.dispose?.();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
        else o.material.dispose?.();
      }
    });
  };

  return group;
}
